#include <iostream>
#include <vector>
#include <queue>
#include <unordered_map>
#include <limits>
using namespace std;

typedef pair<int, string> pis;

unordered_map<string, int> dijkstra(unordered_map<string, unordered_map<string, int>>& graph, string start) {
    unordered_map<string, int> distances;
    for (auto& node : graph) {
        distances[node.first] = INT_MAX;
    }
    distances[start] = 0;

    priority_queue<pis, vector<pis>, greater<pis>> pq;
    pq.push({0, start});

    while (!pq.empty()) {
        int currentDist = pq.top().first;
        string currentNode = pq.top().second;
        pq.pop();

        if (currentDist > distances[currentNode]) continue;

        for (auto& neighbor : graph[currentNode]) {
            int distance = currentDist + neighbor.second;

            if (distance < distances[neighbor.first]) {
                distances[neighbor.first] = distance;
                pq.push({distance, neighbor.first});
            }
        }
    }

    return distances;
}

int main() {
    unordered_map<string, unordered_map<string, int>> graph = {
        {"A", {{"B", 4}, {"C", 2}}},
        {"B", {{"C", 1}, {"D", 5}}},
        {"C", {{"D", 8}, {"E", 10}}},
        {"D", {{"E", 2}}},
        {"E", {}}
    };

    auto result = dijkstra(graph, "A");
    cout << "Shortest distances from A:" << endl;
    for (auto& pair : result) {
        cout << pair.first << ": " << pair.second << endl;
    }

    return 0;
}

