function dijkstra(graph, start) {
    // Find shortest paths from start node to all other nodes
    const distances = {};
    const visited = new Set();
    const priorityQueue = [[0, start]];

    // Initialize distances
    for (const node in graph) {
        distances[node] = Infinity;
    }
    distances[start] = 0;

    while (priorityQueue.length > 0) {
        // Sort to get minimum distance
        priorityQueue.sort((a, b) => a[0] - b[0]);
        const [currentDistance, currentNode] = priorityQueue.shift();

        if (visited.has(currentNode)) continue;
        visited.add(currentNode);

        for (const neighbor in graph[currentNode]) {
            const weight = graph[currentNode][neighbor];
            const distance = currentDistance + weight;

            if (distance < distances[neighbor]) {
                distances[neighbor] = distance;
                priorityQueue.push([distance, neighbor]);
            }
        }
    }

    return distances;
}

// Example graph
const graph = {
    'A': {'B': 4, 'C': 2},
    'B': {'C': 1, 'D': 5},
    'C': {'D': 8, 'E': 10},
    'D': {'E': 2},
    'E': {}
};

const result = dijkstra(graph, 'A');
console.log('Shortest distances from A:', result);
